import{_ as t,o as r,c as o,aN as e}from"./chunks/framework.D31DlcCL.js";const s="/img/math-shape-patterns-2.svg",c=JSON.parse('{"title":"奥数进阶：图形规律（二）矩阵与多维变化","description":"当图形排成方阵，规律就变得立体起来。本文带你学习如何破解图形矩阵题，从横向、纵向以及整体特征三个维度锁定消失的图形。","frontmatter":{"title":"奥数进阶：图形规律（二）矩阵与多维变化","date":"2026-02-18T09:00:00.000Z","categories":["数学"],"tags":["小学奥数","图形规律","矩阵推理","观察力"],"description":"当图形排成方阵，规律就变得立体起来。本文带你学习如何破解图形矩阵题，从横向、纵向以及整体特征三个维度锁定消失的图形。","cover":"/img/math-shape-patterns-2.svg","top_img":"/img/math-shape-patterns-2.svg","toc_number":true},"headers":[],"relativePath":"posts/primary-math-olympiad-shape-patterns-2.md","filePath":"posts/primary-math-olympiad-shape-patterns-2.md","lastUpdated":null}'),l={name:"posts/primary-math-olympiad-shape-patterns-2.md"};function i(n,a,h,p,d,g){return r(),o("div",null,[...a[0]||(a[0]=[e('<h1 id="奥数进阶-图形规律-二-矩阵与多维变化" tabindex="-1">奥数进阶：图形规律（二）矩阵与多维变化 <a class="header-anchor" href="#奥数进阶-图形规律-二-矩阵与多维变化" aria-label="Permalink to &quot;奥数进阶：图形规律（二）矩阵与多维变化&quot;">​</a></h1><p>在基础篇中，我们学习了单排图形的旋转和数量变化。但在更高级的题目里，图形往往以 <strong>3×3 矩阵</strong> 的形式出现。</p><p>这时候，规律不再是一条线，而是一张网。你需要同时观察横行、竖列，甚至是斜向的特征。</p><hr><h2 id="一、-核心法宝-行列搜寻法" tabindex="-1">一、 核心法宝：行列搜寻法 <a class="header-anchor" href="#一、-核心法宝-行列搜寻法" aria-label="Permalink to &quot;一、 核心法宝：行列搜寻法&quot;">​</a></h2><p>解决图形矩阵题，有三个主要的观察方向：</p><p><img src="'+s+'" alt="图形矩阵逻辑图解"></p><ol><li><strong>横向看（行规律）</strong>： 观察第一行、第二行，看看它们是不是遵循同样的变换逻辑（如：形状不变，颜色变深）。</li><li><strong>纵向看（列规律）</strong>： 如果横着看不出来，就竖着看。第一列、第二列的规律通常会延续到第三列。</li><li><strong>整体看（元素统计）</strong>： 这种最常见。每一行（或每一列）都有固定的几个元素，只是位置打乱了。</li></ol><hr><h2 id="二、-实战模型解析" tabindex="-1">二、 实战模型解析 <a class="header-anchor" href="#二、-实战模型解析" aria-label="Permalink to &quot;二、 实战模型解析&quot;">​</a></h2><h3 id="模型-1-缺啥补啥-元素统计" tabindex="-1">模型 1：缺啥补啥（元素统计） <a class="header-anchor" href="#模型-1-缺啥补啥-元素统计" aria-label="Permalink to &quot;模型 1：缺啥补啥（元素统计）&quot;">​</a></h3><p><strong>【例题 1】</strong>：如封面图所示，每行都有圆、方、三角三种形状。 <strong>解析</strong>：</p><ul><li>第一行：圆、方、三角。</li><li>第二行：方、三角、圆。</li><li>第三行：三角、圆、( \\quad )。 <strong>答案</strong>：显然缺一个<strong>正方形</strong>。</li></ul><h3 id="模型-2-叠加与去同存异" tabindex="-1">模型 2：叠加与去同存异 <a class="header-anchor" href="#模型-2-叠加与去同存异" aria-label="Permalink to &quot;模型 2：叠加与去同存异&quot;">​</a></h3><p>有些题是把前两个图形“叠”在一起变成第三个。</p><ul><li><strong>简单叠加</strong>：A + B = C。</li><li><strong>去同存异</strong>：把 A 和 B 相同的部分删掉，剩下的拼在一起。</li></ul><hr><h2 id="三、-进阶技巧-细节微调" tabindex="-1">三、 进阶技巧：细节微调 <a class="header-anchor" href="#三、-进阶技巧-细节微调" aria-label="Permalink to &quot;三、 进阶技巧：细节微调&quot;">​</a></h2><p>有时候形状没变，但里面的小细节在变。</p><ul><li><strong>填充色</strong>：阴影部分在顺时针移动。</li><li><strong>开口方向</strong>：小缺口每次向右旋转 90 度。</li><li><strong>线条数量</strong>：每行图形内部的线条数相加等于 10。</li></ul><hr><h2 id="四、-避坑指南-不要被颜色干扰" tabindex="-1">四、 避坑指南：不要被颜色干扰 <a class="header-anchor" href="#四、-避坑指南-不要被颜色干扰" aria-label="Permalink to &quot;四、 避坑指南：不要被颜色干扰&quot;">​</a></h2><p>有时候题目会用鲜艳的颜色来误导你，其实规律只藏在形状的边数里。</p><ul><li><strong>策略</strong>：先看大轮廓，再看小细节，最后看颜色。</li></ul><hr><h2 id="五、-练一练-视觉逻辑闯关" tabindex="-1">五、 练一练（视觉逻辑闯关） <a class="header-anchor" href="#五、-练一练-视觉逻辑闯关" aria-label="Permalink to &quot;五、 练一练（视觉逻辑闯关）&quot;">​</a></h2><ol><li><strong>基础关</strong>：第一行是 1, 2, 3 条线；第二行是 2, 3, 4 条线；第三行是 3, 4, ( \\quad ) 条线？</li><li><strong>进阶关</strong>：每一行都有一个笑脸、一个哭脸、一个惊讶脸。如果第三行缺了一个，你会补哪一个？</li><li><strong>挑战关</strong>：观察一个 3×3 矩阵，第一列全是有阴影的，第二列全是空白的，猜猜第三列是什么样的？</li></ol><hr><p><em>总结：矩阵图形题是思维的“拼图”。只要你守住行列的一致性，再复杂的变幻也难不倒你的火眼金睛！</em></p>',29)])])}const u=t(l,[["render",i]]);export{c as __pageData,u as default};
